// Expo config plugin: extra R8 keep rules for release builds (android/app/proguard-rules.pro).
//
// Why: the first release APK crashed on start (2026-11-18, Galaxy F12, Android 13) with
//   NoSuchMethodException: androidx.work.impl.WorkDatabase_Impl.<init> []
// R8 removed the no-argument constructor of the Room database that WorkManager creates by reflection
// (WorkManager backs expo-background-task, our offline outbox). Keep every Room database's constructor.
// android/ is generated by `expo prebuild`, so the rules live here and are re-applied on every prebuild.
const { withDangerousMod } = require('expo/config-plugins');
const fs = require('node:fs');
const path = require('node:path');

const MARK = '# --- toyam: release keep rules (plugins/with-release-keep-rules.js) ---';
const RULES = `
${MARK}
# Room databases (WorkManager's WorkDatabase_Impl and any other) are instantiated by reflection.
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class androidx.work.impl.WorkDatabase_Impl { *; }
# WorkManager workers and input mergers are created by class name.
-keep class * extends androidx.work.ListenableWorker { <init>(android.content.Context, androidx.work.WorkerParameters); }
-keep class * extends androidx.work.InputMerger { <init>(); }
`;

module.exports = function withReleaseKeepRules(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const file = path.join(cfg.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
      if (!current.includes(MARK)) fs.writeFileSync(file, current.trimEnd() + '\n' + RULES);
      return cfg;
    },
  ]);
};
